module hr_optimization (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] day_index,\n    input [3:0] f_i,\n    input [3:0] h_i,\n    output reg [3:0] hr_id,\n    output reg done,\n    output reg [3:0] min_hr\n);\n\n// Parameters\nlocalparam [3:0] MAX_DAYS    = 4'd16;\nlocalparam [3:0] MAX_WORKERS = 4'd8;\nlocalparam [3:0] MAX_HR      = 4'd16;\n\n// State declarations\nlocalparam [1:0] IDLE        = 2'd0;\nlocalparam [1:0] PROCESSING  = 2'd1;\nlocalparam [1:0] FINISH      = 2'd2;\n\n// Internal registers\nreg [1:0] state;\nreg [1:0] next_state;\nreg [3:0] stack [0:7];\nreg [3:0] sp;\nreg [15:0] used_hr_mask;\nreg [3:0] max_hr_used;\nreg [3:0] day_counter;\nreg [3:0] fire_count;\nreg [3:0] hire_count;\nreg [3:0] temp_hr;\n\ninteger i;\n\n// Find smallest available HR ID\nfunction [3:0] find_min_hr(input [15:0] used_mask);\n    integer j;\n    begin\n        find_min_hr = 4'd1;  // HR IDs start at 1\n        for (j = 1; j < MAX_HR; j = j + 1) begin\n            if (used_mask[j] == 1'b0) begin\n                find_min_hr = j;\n                j = MAX_HR;  // Exit loop\n            end\n        end\n    end\nendfunction\n\n// Main state machine\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        sp <= 4'd0;\n        max_hr_used <= 4'd1;\n        done <= 1'b0;\n        hr_id <= 4'd0;\n        min_hr <= 4'd0;\n        day_counter <= 4'd0;\n        for (i = 0; i < MAX_WORKERS; i = i + 1) begin\n            stack[i] <= 4'd0;\n        end\n    end else begin\n        state <= next_state;\n\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    next_state <= PROCESSING;\n                    sp <= 4'd0;\n                    max_hr_used <= 4'd1;\n                    day_counter <= 4'd0;\n                    hr_id <= 4'd0;\n                    min_hr <= 4'd0;\n                    for (i = 0; i < MAX_WORKERS; i = i + 1) begin\n                        stack[i] <= 4'd0;\n                    end\n                end\n            end\n\n            PROCESSING: begin\n                used_hr_mask <= 16'd0;\n                fire_count <= (f_i < sp) ? f_i : sp;\n                hire_count <= (h_i + sp > MAX_WORKERS) ? (MAX_WORKERS - sp) : h_i;\n\n                // Mark HR IDs of fired workers\n                for (i = 0; i < fire_count; i = i + 1) begin\n                    used_hr_mask[stack[sp - 1 - i]] <= 1'b1;\n                end\n\n                // Find and assign new HR ID\n                temp_hr <= find_min_hr(used_hr_mask);\n                hr_id <= find_min_hr(used_hr_mask);\n\n                // Update max HR used\n                if (find_min_hr(used_hr_mask) > max_hr_used) begin\n                    max_hr_used <= find_min_hr(used_hr_mask);\n                end\n\n                // Update stack pointer\n                sp <= sp - fire_count + hire_count;\n\n                // Push new hires\n                for (i = 0; i < hire_count; i = i + 1) begin\n                    stack[sp - fire_count + i] <= temp_hr;\n                end\n\n                // Day completion\n                if (day_counter == MAX_DAYS - 4'd1) begin\n                    next_state <= FINISH;\n                end else begin\n                    day_counter <= day_counter + 4'd1;\n                end\n            end\n\n            FINISH: begin\n                done <= 1'b1;\n                min_hr <= max_hr_used;\n                next_state <= IDLE;\n            end\n\n            default: begin\n                next_state <= IDLE;\n            end\n        endcase\n    end\nend\n\n// Next state combinational logic\nalways @(*) begin\n    case (state)\n        IDLE:       next_state = (start) ? PROCESSING : IDLE;\n        PROCESSING: next_state = (day_counter < MAX_DAYS) ? PROCESSING : FINISH;\n        FINISH:     next_state = IDLE;\n        default:    next_state = IDLE;\n    endcase\nend\n\nendmodule